-- Contenu i18n : appartements, services, catégories de services.
-- Le français reste dans les colonnes de base ; les autres langues vivent dans `i18n`.

alter table public.apartments add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.services add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.service_categories add column if not exists i18n jsonb not null default '{}'::jsonb;

update public.services set description = 'Coiffeurs et coiffeuses professionnels se déplacent chez vous, pour une coupe, un brushing ou des tresses.' where slug = 'coiffure-tresses';
delete from public.contact_messages where email ilike '%@example.com';

update public.apartments set i18n = '{"en":{"name":"Les 2 Palmiers – Dream Apartment","summary":"Two bedrooms, a colonnaded terrace and views over the rooftops and the ocean, quiet and high up in Cotonou.","description":"An exceptional furnished apartment on the top floor: open living room, full kitchen, two en-suite bedrooms, and a long balustraded terrace overlooking the palm trees and the ocean.\n\nEverything is ready on arrival — linen, toiletries, water, backup generator. Our team stays reachable 7 days a week for a car, housekeeping, a chef or an outing."},"es":{"name":"Les 2 Palmiers – Apartamento de Ensueño","summary":"Dos dormitorios, terraza con columnas y vistas a los tejados y al océano, tranquilo y en altura en Cotonú.","description":"Un apartamento amueblado excepcional en la última planta: salón abierto, cocina completa, dos dormitorios con baño y una larga terraza con balaustrada que da a las palmeras y al océano.\n\nTodo está listo a la llegada: ropa de cama, productos, agua, grupo electrógeno. Nuestro equipo está disponible los 7 días para el coche, la limpieza, un cocinero o una excursión."},"zh":{"name":"Les 2 Palmiers – 梦想公寓","summary":"两间卧室、带立柱的露台，俯瞰屋顶与海洋，位于科托努高处，宁静安逸。","description":"位于顶层的高品质带家具公寓：开放式客厅、完整厨房、两间带独立卫浴的卧室，以及一条带栏杆的长露台，俯瞰棕榈树与海洋。\n\n入住时一切就绪——床品、洗漱用品、饮用水、备用发电机。我们的团队每周 7 天随时待命，可安排用车、保洁、厨师或出游。"},"ar":{"name":"Les 2 Palmiers – شقة الأحلام","summary":"غرفتا نوم، وشرفة بأعمدة تطل على السطوح والمحيط، في هدوء وعلى ارتفاع في كوتونو.","description":"شقة مفروشة استثنائية في الطابق الأخير: صالة مفتوحة، مطبخ كامل، غرفتا نوم بحمام خاص، وشرفة طويلة بدرابزين تطل على النخيل والمحيط.\n\nكل شيء جاهز عند الوصول — بياضات، مستلزمات، ماء، مولّد احتياطي. فريقنا متاح طوال أيام الأسبوع للسيارة والتنظيف وطاهٍ أو نزهة."},"pt":{"name":"Les 2 Palmiers – Apartamento de Sonho","summary":"Dois quartos, terraço com colunas e vista sobre os telhados e o oceano, tranquilo e em altura em Cotonou.","description":"Um apartamento mobilado excecional no último andar: sala aberta, cozinha completa, dois quartos com casa de banho privativa e um longo terraço com balaustrada virado para as palmeiras e o oceano.\n\nEstá tudo pronto à chegada — roupa de cama, produtos, água, gerador de reserva. A nossa equipa está disponível 7 dias por semana para o carro, a limpeza, um cozinheiro ou um passeio."},"de":{"name":"Les 2 Palmiers – Traumwohnung","summary":"Zwei Schlafzimmer, eine Säulenterrasse und Blick über die Dächer und den Ozean, ruhig und in der Höhe in Cotonou.","description":"Eine außergewöhnliche möblierte Wohnung im obersten Stock: offener Wohnraum, voll ausgestattete Küche, zwei Schlafzimmer mit eigenem Bad und eine lange Terrasse mit Balustrade mit Blick auf die Palmen und den Ozean.\n\nBei der Ankunft ist alles bereit — Wäsche, Pflegeprodukte, Wasser, Notstromaggregat. Unser Team ist 7 Tage die Woche erreichbar für Auto, Reinigung, einen Koch oder einen Ausflug."},"it":{"name":"Les 2 Palmiers – Appartamento da Sogno","summary":"Due camere, terrazza colonnata e vista sui tetti e sull''oceano, tranquillo e in alto a Cotonou.","description":"Un appartamento arredato eccezionale all''ultimo piano: soggiorno aperto, cucina completa, due camere con bagno privato e una lunga terrazza con balaustra affacciata sulle palme e sull''oceano.\n\nTutto è pronto all''arrivo — biancheria, prodotti, acqua, gruppo elettrogeno. Il nostro team è raggiungibile 7 giorni su 7 per l''auto, le pulizie, un cuoco o un''escursione."},"ru":{"name":"Les 2 Palmiers – Апартаменты мечты","summary":"Две спальни, терраса с колоннами и вид на крыши и океан — тихо и на высоте в Котону.","description":"Исключительные меблированные апартаменты на верхнем этаже: открытая гостиная, полностью оборудованная кухня, две спальни с ванными комнатами и длинная терраса с балюстрадой с видом на пальмы и океан.\n\nК приезду всё готово — бельё, средства, вода, резервный генератор. Наша команда на связи 7 дней в неделю: машина, уборка, повар или экскурсия."},"ja":{"name":"Les 2 Palmiers – 夢のアパートメント","summary":"2 つの寝室、列柱のテラス、屋根並みと海を望む眺め。コトヌーの高台で静かに。","description":"最上階にある特別な家具付きアパートメント。オープンなリビング、フル装備のキッチン、バス付きの寝室 2 室、そしてヤシと海を見渡す手すり付きの長いテラス。\n\n到着時にはすべて整っています — リネン、アメニティ、水、非常用発電機。車、清掃、シェフ、外出まで、チームが週 7 日対応します。"}}'::jsonb where slug = 'les-2-palmiers';
update public.apartments set i18n = '{"en":{"name":"The Studio — Fidjrossè","summary":"A bright loft steps from Fidjrossè beach: mezzanine, large glass wall and private rooftop.","description":"A former workshop converted into a loft: double-height ceiling, south-facing glass wall, a mezzanine bedroom and a private rooftop for the end of the day.\n\nPerfect for a couple or a business traveller who wants the beach and the centre a few minutes away. Same team, same on-demand services."},"es":{"name":"El Taller — Fidjrossè","summary":"Un loft luminoso a un paso de la playa de Fidjrossè: altillo, gran ventanal y azotea privada.","description":"Antiguo taller convertido en loft: techo a doble altura, ventanal orientado al sur, un dormitorio en altillo y una azotea privada para el final del día.\n\nPerfecto para una pareja o un viajero de negocios que quiere la playa y el centro a unos minutos. Mismo equipo, mismos servicios a la carta."},"zh":{"name":"工作室 — Fidjrossè","summary":"距 Fidjrossè 海滩仅几步之遥的明亮 loft：夹层、大面积玻璃幕墙和私人屋顶。","description":"由旧工作室改造的 loft：挑高天花板、朝南玻璃幕墙、夹层卧室，以及供傍晚小憩的私人屋顶。\n\n非常适合希望几分钟内即达海滩与市中心的情侣或商务旅客。同一团队，同样的按需服务。"},"ar":{"name":"الأتيليه — فيدجروسيه","summary":"لوفت مضيء على بُعد خطوات من شاطئ فيدجروسيه: ميزانين، واجهة زجاجية كبيرة، وسطح خاص.","description":"ورشة سابقة حُوّلت إلى لوفت: سقف بارتفاع مضاعف، واجهة زجاجية جنوبية، غرفة نوم في الميزانين، وسطح خاص لنهاية اليوم.\n\nمثالي لثنائي أو مسافر أعمال يريد الشاطئ والمركز على بُعد دقائق. الفريق نفسه، والخدمات نفسها عند الطلب."},"pt":{"name":"O Atelier — Fidjrossè","summary":"Um loft luminoso a dois passos da praia de Fidjrossè: mezanino, grande parede de vidro e rooftop privado.","description":"Antigo atelier convertido em loft: pé-direito duplo, parede de vidro virada a sul, um quarto em mezanino e um rooftop privado para o fim do dia.\n\nPerfeito para um casal ou um viajante de negócios que quer a praia e o centro a poucos minutos. Mesma equipa, mesmos serviços a pedido."},"de":{"name":"Das Atelier — Fidjrossè","summary":"Ein heller Loft nur wenige Schritte vom Strand von Fidjrossè: Galerie, große Glasfront und private Dachterrasse.","description":"Eine ehemalige Werkstatt, umgebaut zum Loft: doppelte Raumhöhe, nach Süden ausgerichtete Glasfront, ein Schlafzimmer auf der Galerie und eine private Dachterrasse für den Feierabend.\n\nPerfekt für ein Paar oder einen Geschäftsreisenden, der Strand und Zentrum wenige Minuten entfernt möchte. Gleiches Team, gleiche Services auf Abruf."},"it":{"name":"L''Atelier — Fidjrossè","summary":"Un loft luminoso a due passi dalla spiaggia di Fidjrossè: soppalco, grande vetrata e rooftop privato.","description":"Ex laboratorio trasformato in loft: soffitto a doppia altezza, vetrata esposta a sud, una camera a soppalco e un rooftop privato per fine giornata.\n\nPerfetto per una coppia o un viaggiatore d''affari che vuole la spiaggia e il centro a pochi minuti. Stesso team, stessi servizi su richiesta."},"ru":{"name":"Ателье — Фиджроссе","summary":"Светлый лофт в двух шагах от пляжа Фиджроссе: антресоль, большое остекление и собственная крыша-терраса.","description":"Бывшая мастерская, переоборудованная в лофт: двойная высота потолков, южное остекление, спальня на антресоли и собственная крыша-терраса для вечеров.\n\nИдеально для пары или командированного, которому нужны пляж и центр в нескольких минутах. Та же команда, те же услуги по запросу."},"ja":{"name":"アトリエ — フィジロセ","summary":"フィジロセ・ビーチまで数歩の明るいロフト。メザニン、大きなガラス壁、専用ルーフトップ。","description":"かつての工房を改装したロフト。吹き抜けの天井、南向きのガラス壁、メザニンの寝室、そして一日の終わりのための専用ルーフトップ。\n\nビーチと中心部まで数分の距離を求めるカップルや出張者に最適。同じチーム、同じオンデマンドのサービス。"}}'::jsonb where slug = 'atelier-fidjrosse';

update public.services set i18n = '{"en":{"title":"Car rental","description":"Modern, clean and comfortable vehicles for all your trips."},"es":{"title":"Alquiler de coche","description":"Vehículos modernos, limpios y cómodos para todos sus desplazamientos."},"zh":{"title":"租车","description":"现代、洁净、舒适的车辆，满足您的一切出行。"},"ar":{"title":"تأجير سيارة","description":"مركبات حديثة ونظيفة ومريحة لكل تنقلاتك."},"pt":{"title":"Aluguer de carro","description":"Veículos modernos, limpos e confortáveis para todas as suas deslocações."},"de":{"title":"Autovermietung","description":"Moderne, saubere und komfortable Fahrzeuge für alle Ihre Wege."},"it":{"title":"Noleggio auto","description":"Veicoli moderni, puliti e confortevoli per tutti i tuoi spostamenti."},"ru":{"title":"Аренда автомобиля","description":"Современные, чистые и комфортные автомобили для всех поездок."},"ja":{"title":"レンタカー","description":"清潔で快適な新しい車で、あらゆる移動を。"}}'::jsonb where slug = 'location-voiture';
update public.services set i18n = '{"en":{"title":"Cleaning staff","description":"Qualified professionals for the cleanliness, order and security of your apartment."},"es":{"title":"Personal de limpieza","description":"Profesionales cualificados para la limpieza, el orden y la seguridad de su apartamento."},"zh":{"title":"保洁人员","description":"专业人员，保障公寓的清洁、井然与安全。"},"ar":{"title":"عاملو النظافة","description":"محترفون مؤهلون لنظافة شقتك وترتيبها وأمنها."},"pt":{"title":"Pessoal de limpeza","description":"Profissionais qualificados para a limpeza, a ordem e a segurança do seu apartamento."},"de":{"title":"Reinigungspersonal","description":"Qualifizierte Fachkräfte für Sauberkeit, Ordnung und Sicherheit Ihrer Wohnung."},"it":{"title":"Personale di pulizia","description":"Professionisti qualificati per la pulizia, l''ordine e la sicurezza del tuo appartamento."},"ru":{"title":"Персонал по уборке","description":"Квалифицированные специалисты для чистоты, порядка и безопасности апартаментов."},"ja":{"title":"清掃スタッフ","description":"お部屋の清潔・整頓・安全を担う有資格のプロ。"}}'::jsonb where slug = 'entretien';
update public.services set i18n = '{"fr":{"title":"Coiffure & tresses","description":"Coiffeurs et coiffeuses professionnels se déplacent chez vous, pour une coupe, un brushing ou des tresses."},"en":{"title":"Hair & braids","description":"Professional hairdressers come to you — for a cut, a blow-dry or braids."},"es":{"title":"Peluquería y trenzas","description":"Peluqueros profesionales se desplazan a su domicilio: corte, brushing o trenzas."},"zh":{"title":"美发与编发","description":"专业发型师上门服务——剪发、吹造型或编发。"},"ar":{"title":"تصفيف الشعر والضفائر","description":"مصفّفو شعر محترفون يأتون إليك — قصّ أو سيشوار أو ضفائر."},"pt":{"title":"Cabeleireiro e tranças","description":"Cabeleireiros profissionais deslocam-se até si — corte, brushing ou tranças."},"de":{"title":"Frisör & Zöpfe","description":"Professionelle Frisöre kommen zu Ihnen — für Schnitt, Föhnen oder Zöpfe."},"it":{"title":"Parrucchiere e treccine","description":"Parrucchieri professionisti vengono da te — taglio, piega o treccine."},"ru":{"title":"Причёски и косы","description":"Профессиональные парикмахеры приезжают к вам — стрижка, укладка или косы."},"ja":{"title":"ヘア＆編み込み","description":"プロの美容師がお部屋へ — カット、ブロー、編み込み。"}}'::jsonb where slug = 'coiffure-tresses';
update public.services set i18n = '{"en":{"title":"Private chef","description":"Home-cooked dishes, prepared to your tastes and preferences."},"es":{"title":"Cocinero a domicilio","description":"Platos caseros, preparados según sus gustos y preferencias."},"zh":{"title":"私人厨师","description":"家常菜肴，按您的口味与偏好烹制。"},"ar":{"title":"طاهٍ في المنزل","description":"أطباق منزلية، تُحضَّر وفق ذوقك وتفضيلاتك."},"pt":{"title":"Chef ao domicílio","description":"Pratos caseiros, preparados segundo os seus gostos e preferências."},"de":{"title":"Privatkoch","description":"Hausgemachte Gerichte, nach Ihrem Geschmack zubereitet."},"it":{"title":"Cuoco a domicilio","description":"Piatti fatti in casa, preparati secondo i tuoi gusti e le tue preferenze."},"ru":{"title":"Повар на дом","description":"Домашние блюда, приготовленные по вашему вкусу и предпочтениям."},"ja":{"title":"出張シェフ","description":"お好みに合わせて仕上げる家庭料理。"}}'::jsonb where slug = 'cuisinier';
update public.services set i18n = '{"en":{"title":"Pedicure & manicure","description":"Professional care for impeccable hands and feet."},"es":{"title":"Pedicura y manicura","description":"Cuidados profesionales para unas manos y unos pies impecables."},"zh":{"title":"修足与美甲","description":"专业护理，让您的手足无可挑剔。"},"ar":{"title":"العناية بالقدمين واليدين","description":"عناية احترافية ليدين وقدمين لا تشوبهما شائبة."},"pt":{"title":"Pedicure e manicure","description":"Cuidados profissionais para mãos e pés impecáveis."},"de":{"title":"Pediküre & Maniküre","description":"Professionelle Pflege für makellose Hände und Füße."},"it":{"title":"Pedicure e manicure","description":"Trattamenti professionali per mani e piedi impeccabili."},"ru":{"title":"Педикюр и маникюр","description":"Профессиональный уход для безупречных рук и ног."},"ja":{"title":"ペディキュア＆マニキュア","description":"手と足を美しく整えるプロのケア。"}}'::jsonb where slug = 'pedicure-manucure';
update public.services set i18n = '{"en":{"title":"In-home massage","description":"Expert hands for your well-being and relaxation."},"es":{"title":"Masaje a domicilio","description":"Manos expertas para su bienestar y relajación."},"zh":{"title":"上门按摩","description":"专业之手，助您身心放松。"},"ar":{"title":"تدليك في المنزل","description":"أيادٍ خبيرة لراحتك واسترخائك."},"pt":{"title":"Massagem ao domicílio","description":"Mãos experientes para o seu bem-estar e relaxamento."},"de":{"title":"Massage zu Hause","description":"Erfahrene Hände für Ihr Wohlbefinden und Ihre Entspannung."},"it":{"title":"Massaggio a domicilio","description":"Mani esperte per il tuo benessere e il tuo relax."},"ru":{"title":"Массаж на дому","description":"Опытные руки для вашего благополучия и расслабления."},"ja":{"title":"出張マッサージ","description":"心身のやすらぎのための熟練の手技。"}}'::jsonb where slug = 'massage';
update public.services set i18n = '{"en":{"title":"Top-ups & transactions","description":"MTN, Moov and Celtis top-ups, plus fast transactions."},"es":{"title":"Recargas y transacciones","description":"Recargas MTN, Moov y Celtis, y transacciones rápidas."},"zh":{"title":"充值与交易","description":"MTN、Moov 和 Celtis 充值，以及快速交易。"},"ar":{"title":"شحن الرصيد والمعاملات","description":"شحن MTN وMoov وCeltis، ومعاملات سريعة."},"pt":{"title":"Recargas e transações","description":"Recargas MTN, Moov e Celtis, e transações rápidas."},"de":{"title":"Aufladungen & Transaktionen","description":"MTN-, Moov- und Celtis-Aufladungen sowie schnelle Transaktionen."},"it":{"title":"Ricariche e transazioni","description":"Ricariche MTN, Moov e Celtis, e transazioni rapide."},"ru":{"title":"Пополнения и платежи","description":"Пополнения MTN, Moov и Celtis, быстрые платежи."},"ja":{"title":"チャージと送金","description":"MTN・Moov・Celtis のチャージと、すばやい送金。"}}'::jsonb where slug = 'recharge-transactions';
update public.services set i18n = '{"en":{"title":"Tailoring at home","description":"Professional tailors at your service, wherever you are."},"es":{"title":"Costura a domicilio","description":"Sastres profesionales a su servicio, esté donde esté."},"zh":{"title":"上门裁缝","description":"专业裁缝为您服务，无论您身在何处。"},"ar":{"title":"خياطة في المنزل","description":"خياطون محترفون في خدمتك، أينما كنت."},"pt":{"title":"Costura ao domicílio","description":"Alfaiates profissionais ao seu serviço, onde quer que esteja."},"de":{"title":"Schneiderei zu Hause","description":"Professionelle Schneider zu Ihren Diensten, wo immer Sie sind."},"it":{"title":"Sartoria a domicilio","description":"Sarti professionisti al tuo servizio, ovunque tu sia."},"ru":{"title":"Пошив на дому","description":"Профессиональные портные к вашим услугам, где бы вы ни были."},"ja":{"title":"出張仕立て","description":"どこにいても、プロの仕立て屋がお手伝い。"}}'::jsonb where slug = 'couture';
update public.services set i18n = '{"en":{"title":"Childcare","description":"Professional nannies, reliable and available 24/7."},"es":{"title":"Cuidado de niños","description":"Niñeras profesionales, fiables y disponibles 24/7."},"zh":{"title":"儿童看护","description":"专业保姆，可靠且全天候待命。"},"ar":{"title":"رعاية الأطفال","description":"مربيات محترفات، موثوقات ومتاحات على مدار الساعة."},"pt":{"title":"Babysitting","description":"Amas profissionais, de confiança e disponíveis 24/7."},"de":{"title":"Kinderbetreuung","description":"Professionelle Betreuerinnen, zuverlässig und rund um die Uhr verfügbar."},"it":{"title":"Babysitting","description":"Babysitter professionali, affidabili e disponibili 24/7."},"ru":{"title":"Няня для детей","description":"Профессиональные няни — надёжные и доступные круглосуточно."},"ja":{"title":"ベビーシッター","description":"信頼できるプロのシッターが 24 時間対応。"}}'::jsonb where slug = 'garde-enfants';
update public.services set i18n = '{"en":{"title":"Bespoke","description":"A specific need? We adapt our services to your request."},"es":{"title":"A medida","description":"¿Una necesidad concreta? Adaptamos nuestros servicios a su solicitud."},"zh":{"title":"量身定制","description":"有特别需求？我们按您的要求调整服务。"},"ar":{"title":"حسب الطلب","description":"حاجة خاصة؟ نكيّف خدماتنا وفق طلبك."},"pt":{"title":"À medida","description":"Uma necessidade específica? Adaptamos os nossos serviços ao seu pedido."},"de":{"title":"Maßgeschneidert","description":"Ein besonderer Wunsch? Wir passen unsere Leistungen an Ihre Anfrage an."},"it":{"title":"Su misura","description":"Un''esigenza particolare? Adattiamo i nostri servizi alla tua richiesta."},"ru":{"title":"Индивидуально","description":"Особая потребность? Мы адаптируем услуги под ваш запрос."},"ja":{"title":"オーダーメイド","description":"特別なご要望は？ ご依頼に合わせて調整します。"}}'::jsonb where slug = 'sur-mesure';

update public.service_categories set i18n = '{"en":{"label":"Home & upkeep"},"es":{"label":"Hogar y mantenimiento"},"zh":{"label":"居家与维护"},"ar":{"label":"المنزل والصيانة"},"pt":{"label":"Casa e manutenção"},"de":{"label":"Haus & Instandhaltung"},"it":{"label":"Casa e manutenzione"},"ru":{"label":"Дом и обслуживание"},"ja":{"label":"住まいとメンテナンス"}}'::jsonb where slug = 'maison-entretien';
